#if UNITY_EDITOR
using UnityEngine;using UnityEditor;using System.Collections;using System.Linq;using System.IO;
namespace Abyss.Story {
public class Revision14Verification:MonoBehaviour {
 System.Collections.Generic.List<string> results=new();int errors;void OnEnable()=>Application.logMessageReceived+=Log;void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception){errors++;File.AppendAllText("Tools/Revision14/errors.txt",m+"\n"+s);}}void OnDisable()=>Application.logMessageReceived-=Log;
 void Check(bool ok,string label){results.Add((ok?"PASS ":"FAIL ")+label);File.WriteAllLines("Tools/Revision14/results.txt",results);}
 void Capture(string name){var cam=Camera.main;var position=cam.transform.position;if(name!="journey"&&!name.StartsWith("seam"))cam.transform.position=new Vector3(-150,-21,-10);var rt=RenderTexture.GetTemporary(1280,720,24);var old=cam.targetTexture;var active=RenderTexture.active;cam.targetTexture=rt;var canvas=FindFirstObjectByType<UnderwaterStoryUI>().GetComponentInChildren<Canvas>();float scale=canvas.scaleFactor;canvas.scaleFactor=720f/1080;foreach(var text in canvas.GetComponentsInChildren<UnityEngine.UI.Text>())text.SetAllDirty();Canvas.ForceUpdateCanvases();cam.Render();RenderTexture.active=rt;var t=new Texture2D(1280,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1280,720),0,0);t.Apply();File.WriteAllBytes("Tools/Revision14/"+name+".png",t.EncodeToPNG());Destroy(t);cam.targetTexture=old;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);cam.transform.position=position;canvas.scaleFactor=scale;foreach(var text in canvas.GetComponentsInChildren<UnityEngine.UI.Text>())text.SetAllDirty();}
 IEnumerator Start(){yield return new WaitForSeconds(1);var story=FindFirstObjectByType<UnderwaterDayStory>();var env=story.GetComponent<WarEnvironment>();var habitat=FindFirstObjectByType<OceanHabitat>();story.ui.Clear();Check(env.Stage==0,"Initial chapter retains clean water stage");Capture("clean");story.secondChapter.BeginSecondChapter();yield return new WaitForSeconds(2);Check(env.Stage==1,"Announcement chapter uses mild polluted stage");yield return new WaitForSeconds(2.2f);Capture("announcement");int mild=env.GetComponentsInChildren<WarDebris>().Length;story.thirdChapter.BeginThirdChapter();yield return new WaitForSeconds(2);Check(env.Stage==2,"Shark journey uses stronger polluted stage");story.thirdChapter.hazards.Halt();story.player.GetComponent<Rigidbody2D>().position=new Vector2(-110,-22);Check(habitat.Allowed(new OceanSpecies{family=HabitatFamily.ReefFish},new Vector2(-100,-20))&&habitat.TargetCount(HabitatFamily.ReefFish,new Vector2(-100,-20))==8,"Existing habitat allows eight sparse roaming fish along battle route");yield return new WaitForSeconds(10);Check(env.GetComponentsInChildren<WarDebris>().Length>mild,"Journey adds more litter than announcement");Check(env.GetComponentsInChildren<WarDebris>().Any(d=>d.suspended&&!d.heavy),"Some light waste floats within the water column");Check(env.maximumWaste==64&&env.journeyWaste==52&&env.maximumCorpses==8,"Trash and corpse budgets remain bounded");
 Check(habitat.Population.Any(c=>c&&c.enabled&&c.definition.family==HabitatFamily.ReefFish&&c.transform.position.x>-160&&c.transform.position.x<170),"Existing spawner actually populates open battle route with living fish");Capture("journey");foreach(float x in new[]{-150f,-134f,-118f,-102f,-86f}){var old=Camera.main.transform.position;Camera.main.transform.position=new Vector3(x,0,-10);Capture("seam"+x);Camera.main.transform.position=old;}var sky=FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None).Where(r=>r.name.StartsWith("Sky")).ToArray();Check(sky.All(r=>r.sharedMaterial.shader==env.pollutionShader),"All original, extended and shore sky tiles share chapter pollution shader");var block=new MaterialPropertyBlock();float minimum=1,maximum=0;foreach(var skyTile in sky){skyTile.GetPropertyBlock(block);float level=block.GetFloat("_Pollution");minimum=Mathf.Min(minimum,level);maximum=Mathf.Max(maximum,level);}Check(minimum>.7f&&maximum-minimum<.001f,"All sky tiles use identical progressive pollution amount");var cameraPosition=Camera.main.transform.position;Camera.main.transform.position=new Vector3(-56,16,-10);Capture("seam-ship-sky");Camera.main.transform.position=cameraPosition;var fish=new GameObject("Test route reef fish");var r=fish.AddComponent<SpriteRenderer>();r.sprite=story.player.swim[0];fish.transform.position=new Vector2(-100,story.player.surfaceY-.8f);var roaming=fish.AddComponent<RoamingCreature>();roaming.definition=new OceanSpecies{family=HabitatFamily.ReefFish};Check(env.StrikeFish((Vector2)fish.transform.position+Vector2.up,(Vector2)fish.transform.position+Vector2.down),"Cannon sweep kills decorative route fish");Check(!env.StrikeFish((Vector2)fish.transform.position+Vector2.up,(Vector2)fish.transform.position+Vector2.down),"Already dead fish cannot consume death budget twice");yield return new WaitForSeconds(2);Check(!roaming.enabled&&Mathf.Abs(Mathf.DeltaAngle(fish.transform.eulerAngles.z,180))<1&&fish.transform.position.y<=story.player.surfaceY,"Killed fish turns belly-up and stops at actual surface");Check(story.GetComponent<BrineDischarge>().outlet.GetComponentInChildren<SpriteRenderer>().sharedMaterial.shader!=env.pollutionShader&&story.player.visual.sharedMaterial.shader!=env.pollutionShader,"Pollution material excludes player and existing discharge effect");Check(errors==0,"No new runtime errors");EditorApplication.isPlaying=false;}
}}
#endif
